package interfaces;

import javax.swing.*;
import javax.swing.border.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.geom.*;

final class Estilo {
 static final Color NAVY = new Color(12,33,65), BLUE = new Color(22,106,219), BG = new Color(243,248,254), TEXT = new Color(20,39,69), MUTED = new Color(103,121,146), BORDER = new Color(213,226,241), GREEN = new Color(21,149,83), RED = new Color(205,63,67);
 static Font f(int size, boolean bold){return new Font("Segoe UI",bold?Font.BOLD:Font.PLAIN,size);}
 static JLabel label(String s,int size,boolean bold,Color c){JLabel l=new JLabel(s);l.setFont(f(size,bold));l.setForeground(c);return l;}
 static JPanel clear(LayoutManager m){JPanel p=new JPanel(m);p.setOpaque(false);return p;}
 static JPanel page(String title,String subtitle,String icon){JPanel p=new JPanel(new BorderLayout(0,19));p.setBackground(BG);p.setBorder(new EmptyBorder(27,28,28,28)); JPanel h=clear(new BorderLayout(12,0));h.add(new JLabel(new Glyph(icon,36,BLUE)),BorderLayout.WEST); JPanel x=clear(new GridLayout(2,1));x.add(label(title,27,true,TEXT));x.add(label(subtitle,13,false,MUTED));h.add(x);p.add(h,BorderLayout.NORTH);return p;}
 static Rounded card(LayoutManager l){Rounded p=new Rounded(Color.WHITE,BORDER,18);p.setLayout(l);p.setBorder(new EmptyBorder(18,19,18,19));return p;}
 static JButton btn(String name,String icon,Color color){Button b=new Button(name,color);if(icon!=null)b.setIcon(new Glyph(icon,17,Color.WHITE));return b;}
 static JButton outline(String name,String icon){Button b=new Button(name,Color.WHITE);b.setForeground(TEXT);b.line=BORDER;if(icon!=null)b.setIcon(new Glyph(icon,17,TEXT));return b;}
 static JTextField field(){JTextField t=new JTextField();t.setFont(f(14,false));t.setForeground(TEXT);t.setBorder(new CompoundBorder(new LineBorder(BORDER,1,true),new EmptyBorder(9,12,9,12)));return t;}
 static JPanel actions(){return clear(new FlowLayout(FlowLayout.LEFT,9,0));}
 static void table(JTable t){t.setFont(f(14,false));t.setRowHeight(42);t.setShowGrid(false);t.setShowHorizontalLines(true);t.setGridColor(new Color(238,243,249));t.setSelectionBackground(new Color(220,238,255));t.setSelectionForeground(TEXT);t.setBackground(Color.WHITE);t.setForeground(TEXT);t.setFillsViewportHeight(true);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);JTableHeader h=t.getTableHeader();h.setPreferredSize(new Dimension(10,43));h.setFont(f(13,true));h.setBackground(new Color(225,237,250));h.setForeground(TEXT);h.setReorderingAllowed(false);t.setDefaultRenderer(Object.class,new DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean sel,boolean foc,int row,int col){super.getTableCellRendererComponent(table,value,sel,foc,row,col);setBorder(new EmptyBorder(0,12,0,7));setBackground(sel?table.getSelectionBackground():row%2==0?Color.WHITE:new Color(250,252,255));setForeground(TEXT);return this;}});}
 static JScrollPane scroll(JTable t){JScrollPane p=new JScrollPane(t);p.setBorder(new LineBorder(BORDER));p.getViewport().setBackground(Color.WHITE);return p;}
 static void msg(Component p,String m){JOptionPane.showMessageDialog(p,m,"Sistema de Gestão Académica",JOptionPane.INFORMATION_MESSAGE);}
 static void warn(Component p,String m){JOptionPane.showMessageDialog(p,m,"Atenção",JOptionPane.WARNING_MESSAGE);}
 static boolean yes(Component p,String s){return JOptionPane.showConfirmDialog(p,s,"Confirmação",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
 static JPanel form(){return clear(new GridBagLayout());}
 static void row(JPanel p,String text,JComponent field,int row){GridBagConstraints c=new GridBagConstraints();c.gridy=row;c.gridx=0;c.anchor=GridBagConstraints.WEST;c.insets=new Insets(6,0,7,14);p.add(label(text,13,true,TEXT),c);c.gridx=1;c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;c.insets=new Insets(6,0,7,0);p.add(field,c);}
 static class Rounded extends JPanel{final Color color,border;final int radius;Rounded(Color c,Color b,int r){color=c;border=b;radius=r;setOpaque(false);}@Override protected void paintComponent(Graphics g){Graphics2D d=(Graphics2D)g.create();d.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);d.setColor(color);d.fillRoundRect(0,0,getWidth()-1,getHeight()-1,radius,radius);if(border!=null){d.setColor(border);d.drawRoundRect(0,0,getWidth()-1,getHeight()-1,radius,radius);}d.dispose();super.paintComponent(g);}}
 static class Button extends JButton{final Color color;Color line;Button(String text,Color c){super(text);color=c;setForeground(Color.WHITE);setFont(f(13,true));setOpaque(false);setContentAreaFilled(false);setBorder(new EmptyBorder(10,14,10,14));setIconTextGap(8);setFocusPainted(false);setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));}@Override protected void paintComponent(Graphics g){Graphics2D d=(Graphics2D)g.create();d.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);d.setColor(getModel().isPressed()?color.darker():color);d.fillRoundRect(0,0,getWidth()-1,getHeight()-1,12,12);if(line!=null){d.setColor(line);d.drawRoundRect(0,0,getWidth()-1,getHeight()-1,12,12);}d.dispose();super.paintComponent(g);}}
 static class Glyph implements Icon{final String k;final int size;final Color c;Glyph(String k,int s,Color c){this.k=k;size=s;this.c=c;}public int getIconWidth(){return size;}public int getIconHeight(){return size;}public void paintIcon(Component comp,Graphics g,int x,int y){Graphics2D d=(Graphics2D)g.create();d.translate(x,y);d.scale(size/24.0,size/24.0);d.setColor(c);d.setStroke(new BasicStroke(2.1f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));d.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);switch(k){case "home":d.drawLine(3,11,12,3);d.drawLine(12,3,21,11);d.drawLine(6,10,6,21);d.drawLine(18,10,18,21);d.drawLine(6,21,18,21);d.drawRect(10,14,4,7);break;case "users":d.drawOval(8,3,8,8);d.drawArc(3,13,18,15,0,180);d.drawArc(-2,11,9,10,25,130);d.drawArc(17,11,9,10,25,130);break;case "book":d.drawLine(12,6,12,20);d.drawLine(12,6,3,4);d.drawLine(3,4,3,19);d.drawLine(3,19,12,20);d.drawLine(12,6,21,4);d.drawLine(21,4,21,19);d.drawLine(21,19,12,20);break;case "clip":d.drawRoundRect(5,5,14,17,2,2);d.drawRoundRect(9,2,6,5,2,2);d.drawLine(9,12,15,12);d.drawLine(9,16,15,16);break;case "search":d.drawOval(3,3,13,13);d.drawLine(14,14,21,21);break;case "exit":d.drawLine(4,4,4,20);d.drawLine(4,4,13,4);d.drawLine(4,20,13,20);d.drawLine(10,12,21,12);d.drawLine(16,7,21,12);d.drawLine(16,17,21,12);break;case "plus":d.drawLine(12,4,12,20);d.drawLine(4,12,20,12);break;case "edit":d.drawLine(5,18,16,7);d.drawLine(8,21,19,10);d.drawLine(5,18,8,21);d.drawLine(16,7,19,10);break;case "delete":d.drawLine(5,7,19,7);d.drawLine(9,4,15,4);d.drawLine(7,7,8,21);d.drawLine(17,7,16,21);d.drawLine(8,21,16,21);d.drawLine(11,10,11,18);d.drawLine(14,10,14,18);break;case "refresh":d.drawArc(4,4,16,16,30,270);d.drawLine(18,3,20,10);d.drawLine(20,10,13,9);break;case "cap":d.fillPolygon(new int[]{1,12,23,12},new int[]{9,3,9,15},4);d.fillRoundRect(6,13,12,5,2,2);d.drawLine(22,9,22,18);break;case "x":d.drawLine(5,5,19,19);d.drawLine(19,5,5,19);break;default:d.fillOval(9,9,6,6);}d.dispose();}}
 private Estilo(){}
}
